package com.yonlab.vision;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.util.Base64;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;

/** Actual metadata cards and explicit escaped offline HTML/CSV sharing. */
public class OneReportsActivity extends YOnActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor(r->new Thread(r,"yon-one-reports"));private int generation,limit=40;private boolean closed,busy;private String filter="all",modelFilter="";private LinearLayout list,filters;private TextView count,overview;private Button html,csv;private List<OneReportRows.Row> rows=Collections.emptyList();private ScrollView contentScroll;private float position;
 @Override public void onCreate(Bundle b){super.onCreate(b);modelFilter=b==null?getIntent().getStringExtra("model_id"):b.getString("modelFilter","");if(modelFilter==null)modelFilter="";if(b!=null){filter=b.getString("filter","all");limit=b.getInt("limit",40);position=b.getFloat("scrollFraction",0);}build();}
 private void build(){LinearLayout root=OneUi.col(this);root.setBackgroundColor(Ui.BACK);root.addView(OneUi.header(this,"리포트",this::finish),Ui.fill());ScrollView scroll=new ScrollView(this);contentScroll=scroll;LinearLayout body=Ui.column(this);count=Ui.heading(this,"기록을 읽는 중",26);body.addView(count);body.addView(OneUi.muted(this,modelFilter.isEmpty()?"분석 결과부터 비교 보고서까지, 필요한 기록을 찾아보세요":"시험 모델 · "+modelFilter+"\n이 모델의 입력별 실행 기록과 지표를 확인합니다. 공유에도 같은 모델 범위를 적용합니다.",15));overview=Ui.text(this,"",15);body.addView(overview);html=Ui.secondary(this,"HTML 공유",v->share(false));csv=Ui.secondary(this,"CSV 공유",v->share(true));body.addView(Ui.actions(this,html,csv),Ui.fill());filters=OneUi.row(this);OneUi.horizontal(this,body,filters);OneUi.gap(this,body,16);list=OneUi.col(this);list.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->{if(r-l>0&&r-l!=or-ol)list.post(()->{if(!closed&&!rows.isEmpty()){float position=OneUi.scrollFraction(contentScroll);render();OneUi.restoreScroll(contentScroll,position);}});});body.addView(list,Ui.fill());scroll.addView(body,Ui.fill());root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("filter",filter);out.putString("modelFilter",modelFilter);out.putInt("limit",limit);out.putFloat("scrollFraction",OneUi.scrollFraction(contentScroll));}
 @Override protected void onResume(){super.onResume();int token=++generation;io.execute(()->{List<OneReportRows.Row> result=OneReportRows.read(getApplicationContext());runOnUiThread(()->{if(owns(token)){List<OneReportRows.Row> scoped=new ArrayList<>();for(OneReportRows.Row row:result)if(modelFilter.isEmpty()||modelFilter.equals(row.model))scoped.add(row);rows=scoped;render();OneUi.restoreScroll(contentScroll,position);}});});}
 @Override protected void onPause(){position=OneUi.scrollFraction(contentScroll);generation++;super.onPause();}
 @Override public void onConfigurationChanged(android.content.res.Configuration configuration){super.onConfigurationChanged(configuration);position=OneUi.scrollFraction(contentScroll);build();render();OneUi.restoreScroll(contentScroll,position);}
 @Override protected void onDestroy(){closed=true;generation++;io.shutdownNow();super.onDestroy();}
 private boolean owns(int token){return !closed&&!isFinishing()&&!isDestroyed()&&generation==token;}
 private void render(){
  list.removeAllViews();filters.removeAllViews();int completed=0,errors=0;Set<String> savedReports=new HashSet<>();for(OneReportRows.Row row:rows){if("완료".equals(row.state))completed++;if("오류".equals(row.state))errors++;File file=reportFile(row.report);if(file!=null)savedReports.add(reportKey(file));}int savedCount=savedReports.size();count.setText("분석 기록 "+rows.size()+"개");overview.setText("완료 "+completed+"   ·   오류 "+errors+"   ·   저장된 리포트 "+savedCount);html.setEnabled(!busy&&!rows.isEmpty());csv.setEnabled(!busy&&!rows.isEmpty());
  for(String[] item:new String[][]{{"all","전체 기록"},{"saved","저장된 리포트"},{"done","완료"},{"error","오류"}})filters.addView(OneUi.chip(this,item[1],item[0].equals(filter),()->{filter=item[0];limit=40;position=0;render();OneUi.restoreScroll(contentScroll,0);}));
  List<OneReportRows.Row> visible=new ArrayList<>();Set<String> shownReports=new HashSet<>();for(OneReportRows.Row row:rows){if("saved".equals(filter)){File file=reportFile(row.report);if(file!=null&&shownReports.add(reportKey(file)))visible.add(row);}else if("all".equals(filter)||"done".equals(filter)&&"완료".equals(row.state)||"error".equals(filter)&&"오류".equals(row.state))visible.add(row);}
  if(visible.isEmpty()){LinearLayout empty=Ui.panel(this);empty.addView(Ui.heading(this,rows.isEmpty()?(modelFilter.isEmpty()?"첫 모델 시험을 시작하세요":"이 모델의 기록이 없습니다"):"선택한 기록이 없습니다",20));if(rows.isEmpty())empty.addView(Ui.button(this,modelFilter.isEmpty()?"모델 시험 시작":"이 모델로 시험",v->{Intent next=new Intent(this,ModelTestActivity.class);if(!modelFilter.isEmpty())next.putExtra("model_id",modelFilter);startActivity(next);finish();}),Ui.fill());list.addView(empty,Ui.fill());return;}
  Map<String,String> names=new HashMap<>();for(OneCatalog.Feature task:OneCatalog.all())for(OneModels.Entry model:OneModels.list(this,task.id))names.put(model.id,model.title);int columns=Ui.contentColumns(this,list,visible.size());LinearLayout row=null;int shown=Math.min(limit,visible.size());
  for(int i=0;i<shown;i++){if(i%columns==0){row=OneUi.row(this);row.setGravity(android.view.Gravity.TOP);LinearLayout.LayoutParams rp=Ui.fill();rp.bottomMargin=Ui.dp(this,16);list.addView(row,rp);}OneReportRows.Row r=visible.get(i);LinearLayout card=Ui.panel(this),top=OneUi.row(this);top.addView(Ui.heading(this,r.feature,19),new LinearLayout.LayoutParams(0,-2,1));top.addView(Ui.pill(this,r.state,"완료".equals(r.state)));card.addView(top);card.addView(OneUi.muted(this,OneReportRows.time(r.at)+" · "+r.source,12));String modelTitle=names.containsKey(r.model)?names.get(r.model):r.model;if(!r.model.isEmpty())card.addView(Ui.text(this,modelTitle+" · "+r.model,14));String summary=summaryForCard(r,modelTitle);if(!summary.isEmpty())card.addView(Ui.text(this,summary,16));if(r.verifiedCer!=null)card.addView(Ui.text(this,OneModelReport.qualityLabel("CER")+" "+OneModelReport.qualityValue("CER",r.verifiedCer),16));String timing=(!r.load.isEmpty()?"준비 "+r.load+" ms   ":"")+(!r.inference.isEmpty()?"분석 "+r.inference+" ms   ":"")+(!r.elapsed.isEmpty()?"전체 "+r.elapsed+" ms":"");if(!timing.isEmpty())card.addView(OneUi.muted(this,timing,13));if(!r.input.isEmpty())card.addView(OneUi.muted(this,"입력 "+r.input.substring(0,12)+"…",12));File saved=reportFile(r.report);if(saved!=null)card.addView(Ui.secondary(this,"저장된 리포트 열기",v->openReport(saved)),Ui.fill());LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);if(i%columns>0)cp.leftMargin=Ui.dp(this,16);row.addView(card,cp);if(i==shown-1)for(int x=i%columns+1;x<columns;x++)row.addView(new android.view.View(this),new LinearLayout.LayoutParams(0,1,1));}
  if(visible.size()>limit)list.addView(Ui.secondary(this,"더 보기",v->{limit+=40;render();}),Ui.fill());
 }
 /** Presentation only: numeric CER was already gated against the recorded verified reference. */
 static String summaryForCard(OneReportRows.Row row,String modelTitle){
  String summary=row.summary==null?"":row.summary;
  if(row.verifiedCer!=null){String suffix="CER "+OneReportRows.numberValue(row.verifiedCer,"cer");if(summary.equals(suffix))summary="";else if(summary.endsWith(" · "+suffix))summary=summary.substring(0,summary.length()-suffix.length()-3);}
  if("음성".equals(row.source)){for(String prefix:new String[]{modelTitle,row.model})if(prefix!=null&&!prefix.isEmpty()&&summary.startsWith(prefix+" · ")){summary=summary.substring(prefix.length()+3);break;}int separator=summary.indexOf(" · ");String first=separator<0?summary:summary.substring(0,separator);if(Arrays.asList("COMPLETED","FAILED","ERROR","CANCELED","CANCELLED","STOPPED").contains(first)&&OneReportRows.state(first).equals(row.state))summary=separator<0?"":summary.substring(separator+3);}
  return summary;
 }
 private void share(boolean asCsv){if(busy||rows.isEmpty())return;busy=true;html.setEnabled(false);csv.setEnabled(false);int token=generation;List<OneReportRows.Row> snapshot=new ArrayList<>(rows);io.execute(()->{File file=null,pending=null;Exception failure=null;try{List<String[]> cells=new ArrayList<>();String[] headers=Arrays.copyOf(OneReportRows.HEADERS,OneReportRows.HEADERS.length+1);headers[headers.length-1]="자료 출처";for(OneReportRows.Row row:snapshot){String[] values=Arrays.copyOf(row.cells(),headers.length);values[values.length-1]=OneInputAttribution.find(getApplicationContext(),"",row.input).text();cells.add(values);}String logo="";String value=asCsv?OneExportCore.csv(headers,cells):OneExportCore.html("AXSL Vision 분석 리포트",headers,cells,logo);if(closed||Thread.currentThread().isInterrupted())return;file=ImageIO.exported(getApplicationContext(),"AXSL-Vision-Report-"+System.currentTimeMillis()+(asCsv?".csv":".html"));pending=new File(file.getParentFile(),file.getName()+".new");try(FileOutputStream out=new FileOutputStream(pending)){out.write(value.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!pending.renameTo(file))throw new IOException("report commit");}catch(Exception e){failure=e;}finally{if(pending!=null&&pending.exists())pending.delete();}File output=file;Exception error=failure;runOnUiThread(()->{busy=false;if(!owns(token))return;render();if(error!=null||output==null){Ui.error(this,"리포트를 만들 수 없습니다",error);return;}try{Uri uri=ImageIO.uri(this,output);Intent send=new Intent(Intent.ACTION_SEND).setType(asCsv?"text/csv":"text/html").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("AXSL Vision 리포트",uri));startActivity(Intent.createChooser(send,"리포트 공유"));}catch(Exception e){Ui.error(this,"공유 앱을 열 수 없습니다",e);}});});}
 private static String reportKey(File file){try{return file.getCanonicalPath();}catch(IOException error){return file.getAbsolutePath();}}
 private File reportFile(String path){if(path==null||path.isEmpty())return null;File root=new File(getFilesDir(),"exports");File candidate=new File(path);if(!candidate.isAbsolute())candidate=path.startsWith("exports/")?new File(getFilesDir(),path):new File(root,path);return candidate.isFile()&&OneExportCore.safeReportFile(root,candidate)?candidate:null;}
 private void openReport(File file){if(reportFile(file.getAbsolutePath())==null){Ui.error(this,"리포트를 열 수 없습니다",null);return;}try{Uri uri=ImageIO.uri(this,file);String name=file.getName().toLowerCase(Locale.ROOT);String mime=name.endsWith(".html")?"text/html":name.endsWith(".csv")?"text/csv":"application/json";Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);view.setClipData(ClipData.newRawUri("AXSL Vision 리포트",uri));startActivity(Intent.createChooser(view,"리포트 열기"));}catch(Exception e){Ui.error(this,"리포트를 열 수 없습니다",e);}}

}
